import axios from 'axios';
import { auth } from '../firebase';

const api = axios.create({
  baseURL: process.env.REACT_APP_API_URL || 'http://localhost:8080/api',
  withCredentials: true,
});

api.interceptors.request.use((originalConfig) => {
  const config = {
    ...originalConfig,
    headers: { ...(originalConfig.headers || {}) },
  };
  try {
    const stored = localStorage.getItem('user');
    if (stored) {
      const { idToken, token } = JSON.parse(stored);
      const accessToken = idToken || token;
      if (accessToken) {
        config.headers.Authorization = `Bearer ${accessToken}`;
      }
    }
  } catch (e) {
    console.error('Error attaching auth header:', e);
  }
  return config;
});

// 401 hatası (token süresi doldu) durumunda token yenileyip isteği tekrar dene
api.interceptors.response.use(
  response => response,
  async error => {
    const originalRequest = error.config;
    if (error.response?.status === 401 && !originalRequest._retry) {
      originalRequest._retry = true;
      try {
        // Firebase Auth currentUser'dan yeni token al
        const currentUser = auth.currentUser;
        if (currentUser) {
          const newIdToken = await currentUser.getIdToken(true);
          console.log('New ID Token:', newIdToken);
          // localStorage güncelle
          const stored = JSON.parse(localStorage.getItem('user') || '{}');
          localStorage.setItem('user', JSON.stringify({ ...stored, idToken: newIdToken }));
          // header'ı güncelle ve isteği tekrar gönder
          originalRequest.headers.Authorization = `Bearer ${newIdToken}`;
          return api(originalRequest);
        }
      } catch (tokenError) {
        console.error('Token refresh failed:', tokenError);
        // Token yenileme başarısızsa veya currentUser yoksa logout ve login sayfasına yönlendir
        // logout fonksiyonunu çağırıp kullanıcıyı login sayfasına yönlendireceğiz
        // Bu, AuthContext'teki logout fonksiyonu veya benzeri bir global logout mekanizması olabilir.
        // Şimdilik doğrudan localStorage temizleme ve yönlendirme kalabilir,
        // Ancak ideal olanı, AuthContext üzerinden logout tetiklemektir.
        try {
          // Global bir logout fonksiyonunuz varsa onu burada çağırın.
          // Örnek: await globalLogoutFunction();
          // Eğer yoksa, manuel olarak localStorage'ı temizleyip yönlendirin:
          localStorage.removeItem('user');
          // React Router useNavigate hook'u veya window.location ile yönlendirme
          // Eğer bu dosya React component dışında ise window.location tercih edilir.
          if (window.location.pathname !== '/login') {
            window.location.href = '/login';
          }
        } catch (logoutError) {
          console.error('Error during forced logout:', logoutError);
          // En kötü senaryo, yine de login'e yönlendir
          if (window.location.pathname !== '/login') {
            window.location.href = '/login';
          }
        }
      }
    }
    return Promise.reject(error);
  }
);

export default api; 